pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // Fuzz the deciding parameters that initialize receives which include both _changeFee and _feeRate.
    // General rule: after initialize(...) completes successfully, c.feeRate() == _feeRate for all admissible inputs.
    // The mutant that swaps assignment order can break this for some inputs; the fuzzer will find such inputs.
    function testFuzz_property(uint128 virtualBaseTokenReserves, uint128 virtualNftReserves, uint56 _changeFee, uint16 _feeRate, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties, address caller) public {
        // Keep caller non-zero to be a sensible actor
        vm.assume(caller != address(0));
        // Ensure _feeRate within allowed bounds to avoid FeeRateTooHigh revert in both contracts
        vm.assume(_feeRate <= 5000);

        // Call initialize as the fuzzed caller (not necessary to be owner etc. for initialize)
        vm.prank(caller);
        bool ok;
        try c.initialize(address(0), address(0), virtualBaseTokenReserves, virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // If initialize succeeded, the invariant must hold: stored feeRate equals the provided _feeRate.
        // This single assertion is true for the reference and will fail for the mutant for some fuzz inputs.
        if (ok) {
            assertTrue(c.feeRate() == _feeRate);
        } else {
            // If initialization reverted, still assert that contract's feeRate remains the default (0) to be a valid universal property.
            // Note: reference contract reverts only when already initialized or feeRate too high; in those revert cases we don't require any relation to inputs.
            // To keep a single assertion as required by the harness rules, route through a tautological check consistent with behavior: if init reverted, ensure stored feeRate is not an unexpected nonzero set (it should remain 0).
            // We assert that c.feeRate() == 0 when initialize reverted.
            assertTrue(c.feeRate() == 0);
        }
    }
}

