pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    // fuzzed params include feeRate and changeFee which share storage packing and can interact
    function testFuzz_property(uint16 _feeRate, uint56 _changeFee, address _nft, address _baseToken, bytes32 _merkleRoot, bool _useStolenNftOracle, bool _payRoyalties, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves) public {
        // keep feeRate within allowed max (function reverts otherwise) but allow full range up to 5000
        _feeRate = uint16(bound(_feeRate, 0, 5000));

        // keep addresses non-zero to be widely admissible but not required; no tight constraints
        if (_nft == address(0)) _nft = address(1);
        if (_baseToken == address(0)) _baseToken = address(2);

        // call initialize as an external actor (use this contract)
        // wrap call in try/catch to ensure we only assert after successful initialize
        bool ok;
        try c.initialize(_baseToken, _nft, _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, _merkleRoot, _useStolenNftOracle, _payRoyalties) {
            ok = true;
        } catch {
            ok = false;
        }

        // If initialize succeeded, the stored feeRate MUST equal the provided _feeRate argument
        if (ok) {
            assertTrue(c.feeRate() == _feeRate);
        } else {
            // If initialize reverted, nothing to assert about storage. Still consider test passing for that input.
            // Use a vacuous true assertion so test function has exactly one assertTrue invocation path per successful init.
            assertTrue(true);
        }
    }
}
